CREATE OR REPLACE FUNCTION public.platform_save_plan(_id text,_values jsonb,_features text[]) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501'; END IF; IF length(trim(coalesce(_values->>'name','')))<1 THEN RAISE EXCEPTION 'name_required'; END IF; PERFORM id FROM public.platform_plans WHERE id=_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'plan_not_found'; END IF; UPDATE public.platform_plans SET name=trim(_values->>'name'),description=coalesce(_values->>'description',''),price_cents=nullif(_values->>'price_cents','')::integer,max_users=(_values->>'max_users')::integer,active=(_values->>'active')::boolean,benefits=ARRAY(SELECT jsonb_array_elements_text(coalesce(_values->'benefits','[]'::jsonb))) WHERE id=_id; DELETE FROM public.platform_plan_features WHERE plan_id=_id; INSERT INTO public.platform_plan_features(plan_id,feature_id) SELECT _id,id FROM unnest(coalesce(_features,'{}'::text[])) id GROUP BY id; END $$; REVOKE ALL ON FUNCTION public.platform_save_plan(text,jsonb,text[]) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.platform_save_plan(text,jsonb,text[]) TO authenticated;